import XCTest
@testable import CoreComponents

final class TOSV5R2FeeVerifierTests: XCTestCase {
    func testPublicLmsSignatureAndTampering() {
        func hex(_ text: String) -> Data {
            var bytes = [UInt8](); var index = text.startIndex
            while index < text.endIndex { let end = text.index(index, offsetBy: 2); guard let byte = UInt8(text[index..<end], radix: 16) else { XCTFail("bad public vector"); return Data() }; bytes.append(byte); index = end }; return Data(bytes)
        }
        let key = hex("000000010000000800000003555555555555555555555555555555557bcba6979fe84c5f26b43cf43516a6504a1435f70a271b0f148bb90e39d90124")
        let digest = hex("62cf82e86af59d082cfe525c4eeacb41ad6a0fc8e326d0a2f7f9e4fdf54d4a65")
        let signature = hex("")
        XCTAssertTrue(TOSV5R2FeeVerifier.verify(leaf: 12, publicKey: key, digest: digest, signature: signature))
        XCTAssertFalse(TOSV5R2FeeVerifier.verify(leaf: 13, publicKey: key, digest: digest, signature: signature))
        var wrong = key; wrong[59] ^= 1
        XCTAssertFalse(TOSV5R2FeeVerifier.verify(leaf: 12, publicKey: wrong, digest: digest, signature: signature))
        var altered = signature; altered[40] ^= 1
        XCTAssertFalse(TOSV5R2FeeVerifier.verify(leaf: 12, publicKey: key, digest: digest, signature: altered))
    }
}
